"""Official VACE entrypoint trial. Free host only, isolated env, fail-closed."""
import os,sys,subprocess,json,time,base64
from pathlib import Path
OUT=Path('/kaggle/working/vace_trial');OUT.mkdir(exist_ok=True)
TMP=Path('/tmp/vace_trial');TMP.mkdir(exist_ok=True)
os.environ['HF_HOME']=str(TMP/'hf')
os.environ['UV_CACHE_DIR']=str(TMP/'uvcache')
(TMP/'portable_attention.py').write_text('"""Opt-in portable attention experiment for pinned audio-driven Wan repos.\n\nUses query chunks and each sequence\'s real key length. This avoids requiring\nFlashAttention2 on T4. It is a numerical fallback, NOT a quality/performance\nclaim. No upstream files are changed. Single-device only; distributed and\nlocal-window attention are refused rather than approximated silently.\n"""\nclass IntegrationError(RuntimeError): pass\n\n\ndef portable_attention(q, k, v, q_lens=None, k_lens=None, dropout_p=0.,\n                       softmax_scale=None, q_scale=None, causal=False,\n                       window_size=(-1, -1), deterministic=False,\n                       dtype=None, version=None, chunk_size=256):\n    import torch\n    import torch.nn.functional as F\n    if window_size != (-1, -1):\n        raise IntegrationError(\'portable attention does not support local windows\')\n    if dropout_p:\n        raise IntegrationError(\'portable inference attention requires dropout_p=0\')\n    if q.ndim != 4 or k.ndim != 4 or v.ndim != 4:\n        raise IntegrationError(\'attention requires [batch, sequence, heads, dim]\')\n    if q.shape[0] != k.shape[0] or k.shape[:3] != v.shape[:3] or q.shape[2] != k.shape[2]:\n        raise IntegrationError(\'attention batch/head/key/value dimensions mismatch\')\n    if not isinstance(chunk_size, int) or chunk_size < 1:\n        raise IntegrationError(\'chunk_size must be a positive integer\')\n    batch, lq = q.shape[:2]\n    lk = k.shape[1]\n    q_lengths = [lq] * batch if q_lens is None else [int(n) for n in q_lens]\n    k_lengths = [lk] * batch if k_lens is None else [int(n) for n in k_lens]\n    if len(q_lengths) != batch or len(k_lengths) != batch:\n        raise IntegrationError(\'one attention length per batch item is required\')\n    if any(not 0 < n <= lq for n in q_lengths) or any(not 0 < n <= lk for n in k_lengths):\n        raise IntegrationError(\'attention lengths must be positive and within tensors\')\n    out = torch.zeros((batch,lq,q.shape[2],v.shape[-1]),device=q.device,dtype=q.dtype)\n    for b in range(batch):\n        kl = k_lengths[b]\n        keys = k[b,:kl].transpose(0,1).unsqueeze(0)\n        vals = v[b,:kl].transpose(0,1).unsqueeze(0)\n        for start in range(0,q_lengths[b],chunk_size):\n            end = min(start+chunk_size,q_lengths[b])\n            queries=q[b,start:end].transpose(0,1).unsqueeze(0)\n            if dtype is not None:\n                queries, keys, vals = queries.to(dtype),keys.to(dtype),vals.to(dtype)\n            if q_scale is not None:\n                queries=queries*q_scale\n            mask=None\n            if causal:\n                mask = (torch.arange(kl,device=q.device)[None,:] <=\n                        torch.arange(start,end,device=q.device)[:,None])\n            kwargs={} if softmax_scale is None else {\'scale\':softmax_scale}\n            chunk=F.scaled_dot_product_attention(queries,keys,vals,\n                     attn_mask=mask,dropout_p=0.,is_causal=False,**kwargs)\n            out[b,start:end]=chunk.squeeze(0).transpose(0,1).to(out.dtype)\n    return out\n\n\ndef install_portable_attention():\n    """Patch imported aliases, not source files. Call after importing Wan.\n    Explicit opt-in is required; CUDA distributed initialization is refused."""\n    import sys\n    import torch\n    if torch.distributed.is_initialized() and torch.distributed.get_world_size() != 1:\n        raise IntegrationError(\'portable attention is single-device only\')\n    import wan.modules.attention as module\n    original=module.flash_attention\n    replaced=[]\n    for name,obj in list(sys.modules.items()):\n        if name.startswith(\'wan.\') and getattr(obj,\'flash_attention\',None) is original:\n            setattr(obj,\'flash_attention\',portable_attention)\n            replaced.append(name)\n    if not replaced:\n        raise IntegrationError(\'no Wan flash_attention aliases found\')\n    return replaced\n\n\ndef force_fp16_configs_for_t4():\n    """Explicit experimental dtype override after Wan import; no source edit.\n    T4 has no native bf16 support. This is not equivalent to validated output."""\n    import torch\n    from wan.configs import WAN_CONFIGS\n    if not torch.cuda.is_available():\n        raise IntegrationError(\'dtype override requires an actual CUDA host\')\n    if torch.cuda.get_device_capability()[0] != 7:\n        raise IntegrationError(\'Turing-only override requested on a different GPU\')\n    updated=[]\n    for key, cfg in WAN_CONFIGS.items():\n        for name in (\'param_dtype\', \'t5_dtype\', \'clip_dtype\'):\n            if hasattr(cfg,name):\n                setattr(cfg,name,torch.float16)\n        updated.append(key)\n    return updated\n')
(TMP/'infer_vace.py').write_text('"""Experimental T4 execution of pinned VACE library, no source-file patching."""\nimport sys,json,time,hashlib\nfrom pathlib import Path\nimport torch\nROOT=Path(\'/tmp/vace_trial\')\nsys.path.insert(0,str(ROOT/\'VACE/vace\'))\nfrom models.wan import WanVace\nfrom models.wan.configs import WAN_CONFIGS\nfrom wan.utils.utils import cache_video\n# Portable attention has separate numerical evidence; model quality remains unverified.\nexec((ROOT/\'portable_attention.py\').read_text(),globals())\npatched=install_portable_attention()\nfor cfg in WAN_CONFIGS.values():\n cfg.param_dtype=torch.float16\n cfg.t5_dtype=torch.float16\nprint(\'PATCHED_ATTENTION\',patched,flush=True)\nout=Path(\'/kaggle/working/vace_trial\')\nckpt=ROOT/\'weights\'\nfrom huggingface_hub import snapshot_download\nsnapshot_download(\'Wan-AI/Wan2.1-VACE-1.3B\',revision=\'574e6a744642ce3bee319afc31496b88bde8aac4\',local_dir=str(ckpt),allow_patterns=[\'config.json\',\'diffusion_pytorch_model.safetensors\',\'Wan2.1_VAE.pth\',\'models_t5_umt5-xxl-enc-bf16.pth\',\'google/umt5-xxl/*\',\'LICENSE.txt\'])\nprint(\'VACE_WEIGHTS_READY\',flush=True)\npipe=WanVace(WAN_CONFIGS[\'vace-1.3B\'],str(ckpt),t5_cpu=True)\nprint(\'VACE_MODEL_LOADED\',flush=True)\n# Official example reference is a technical capability test, not an episode asset.\nref=str(ROOT/\'VACE/assets/images/girl.png\')\nassert Path(ref).is_file(),ref\nsrc,mask,refs=pipe.prepare_source([None],[None],[[ref]],17,(480,832),0)\nprompt=\'A girl stands in a quiet courtyard. She slowly turns her head toward the camera. Static camera, natural daylight.\'\nt=time.time()\nvid=pipe.generate(prompt,src,mask,refs,size=(480,832),frame_num=17,shift=16,sample_solver=\'unipc\',sampling_steps=8,guide_scale=5.0,seed=42,offload_model=True)\np=out/\'vace_reference_trial.mp4\'\ncache_video(tensor=vid[None],save_file=str(p),fps=16,nrow=1,normalize=True,value_range=(-1,1))\n(out/\'inference.json\').write_text(json.dumps({\'status\':\'generated_not_visually_reviewed\',\'frames\':17,\'steps\':8,\'seed\':42,\'seconds\':time.time()-t,\'sha256\':hashlib.sha256(p.read_bytes()).hexdigest(),\'experimental\':\'fp16 + portable attention on T4\',\'reference\':ref,\'prompt\':prompt},indent=2))\nprint(\'VACE_REFERENCE_TRIAL_GENERATED\',flush=True)\n')
steps=[]
def cmd(args,cwd=None,timeout=1800):
 t=time.time();p=subprocess.run(args,cwd=cwd,capture_output=True,text=True,timeout=timeout,env=os.environ)
 name=f'{len(steps):02d}'
 (OUT/f'{name}.log').write_text(p.stdout+'\n'+p.stderr)
 steps.append({'argv':args,'returncode':p.returncode,'seconds':round(time.time()-t,1),'log':name+'.log'})
 (OUT/'steps.json').write_text(json.dumps(steps,indent=2))
 print('STEP',name,p.returncode,flush=True)
 if p.returncode: raise RuntimeError('step failed: '+name+' '+p.stderr[-600:])
 return p.stdout
try:
 cmd([sys.executable,'-m','pip','install','uv'])
 uv=[sys.executable,'-m','uv']
 cmd(uv+['venv','--python','3.10',str(TMP/'env')])
 py=str(TMP/'env/bin/python')
 cmd(uv+['pip','install','--python',py,'torch==2.5.1','torchvision==0.20.1','--index-url','https://download.pytorch.org/whl/cu124'])
 cmd(uv+['pip','install','--python',py,'diffusers==0.33.1','transformers==4.49.0','accelerate','numpy<2','opencv-python-headless<4.12','easydict','ftfy','imageio','imageio-ffmpeg','einops','dashscope','pycocotools','decord','scikit-image','timm','beautifulsoup4','sentencepiece','protobuf','huggingface_hub','safetensors','tqdm'])
 cmd(['git','clone','https://github.com/ali-vilab/VACE',str(TMP/'VACE')])
 cmd(['git','checkout','48eb44f1c4be87cc65a98bff985a26976841e9f3'],cwd=TMP/'VACE')
 cmd(['git','clone','https://github.com/Wan-Video/Wan2.1',str(TMP/'Wan2.1')])
 cmd(['git','checkout','9737cba9c1c3c4d04b33fcad41c111989865d315'],cwd=TMP/'Wan2.1')
 # No dependency resolution may install unsupported flash-attn behind our back.
 cmd(uv+['pip','install','--python',py,'--no-deps',str(TMP/'Wan2.1')])
 try:
  cmd([py,str(TMP/'VACE/vace/vace_wan_inference.py'),'--help'],cwd=TMP/'VACE')
 except RuntimeError as e:
  print('CLI_HELP_BLOCKED_TRY_CORE_LIBRARY',str(e),flush=True)
 cmd([py,str(TMP/'infer_vace.py')],cwd=TMP/'VACE',timeout=5400)
 (OUT/'status.json').write_text(json.dumps({'status':'inference_subprocess_passed','next':'visual review required'},indent=2))
 print('VACE_TRIAL_SUBPROCESS_PASSED',flush=True)
except Exception as e:
 (OUT/'status.json').write_text(json.dumps({'status':'blocked','error':str(e)},indent=2))
 print('VACE_TRIAL_BLOCKED',str(e),flush=True)
 raise
